// ── Subsystems (each has its own complex API) ─────────────────────
class CartService {
  validate(cartId) {
    console.log(`[Cart] Validating cart ${cartId}`);
    return true; // assume valid
  }
  getItems(cartId) {
    console.log(`[Cart] Fetching items for cart ${cartId}`);
    return [{ name: 'Widget', price: 19.99 }, { name: 'Gadget', price: 34.99 }];
  }
  getTotal(items) {
    return items.reduce((sum, i) => sum + i.price, 0);
  }
}

class InventoryService {
  reserve(items) {
    console.log(`[Inventory] Reserving ${items.length} item(s)`);
  }
  release(items) {
    console.log(`[Inventory] Releasing ${items.length} item(s)`);
  }
}

class PaymentGateway {
  charge(userId, amount) {
    console.log(`[Payment] Charging user ${userId} $${amount.toFixed(2)}`);
    return { receiptId: `REC-${Date.now()}`, amount };
  }
  refund(receiptId) {
    console.log(`[Payment] Refunding receipt ${receiptId}`);
  }
}

class EmailService {
  sendConfirmation(userId, receipt) {
    console.log(`[Email] Sending confirmation to user ${userId}, receipt ${receipt.receiptId}`);
  }
  sendCancellation(userId) {
    console.log(`[Email] Sending cancellation to user ${userId}`);
  }
}

// ── Facade: one simple API for the client ─────────────────────────
class OrderFacade {
  constructor() {
    this._cart      = new CartService();
    this._inventory = new InventoryService();
    this._payment   = new PaymentGateway();
    this._email     = new EmailService();
  }

  placeOrder(cartId, userId) {
    console.log('--- Order Start ---');
    if (!this._cart.validate(cartId)) throw new Error('Invalid cart');

    const items   = this._cart.getItems(cartId);
    const total   = this._cart.getTotal(items);

    this._inventory.reserve(items);

    let receipt;
    try {
      receipt = this._payment.charge(userId, total);
    } catch (err) {
      this._inventory.release(items); // compensate on failure
      throw err;
    }

    this._email.sendConfirmation(userId, receipt);
    console.log('--- Order Complete ---\n');
    return receipt;
  }

  cancelOrder(receiptId, userId, items) {
    console.log('--- Cancel Start ---');
    this._payment.refund(receiptId);
    this._inventory.release(items);
    this._email.sendCancellation(userId);
    console.log('--- Cancel Complete ---\n');
  }
}

// ── Client: knows nothing about the five subsystems ───────────────
const orders = new OrderFacade();
const receipt = orders.placeOrder('cart-001', 'user-42');
// --- Order Start ---
// [Cart] Validating cart cart-001
// [Cart] Fetching items for cart cart-001
// [Inventory] Reserving 2 item(s)
// [Payment] Charging user user-42 $54.98
// [Email] Sending confirmation to user user-42, receipt REC-...
// --- Order Complete ---

// ── Structural skeleton ──────────────────────────────────────────

// Subsystem classes (complex, independent)
class SubsystemA {
  operationA() { return 'SubsystemA: ready'; }
}
class SubsystemB {
  operationB() { return 'SubsystemB: go!'; }
}
class SubsystemC {
  operationC() { return 'SubsystemC: done'; }
}

// Facade: simple interface over the three subsystems
class Facade {
  constructor() {
    this._a = new SubsystemA();
    this._b = new SubsystemB();
    this._c = new SubsystemC();
  }
  // One method replaces three calls the client would otherwise make
  doWork() {
    const results = [
      this._a.operationA(),
      this._b.operationB(),
      this._c.operationC(),
    ];
    return results.join(' | ');
  }
}

// Client
const facade = new Facade();
console.log(facade.doWork());
// SubsystemA: ready | SubsystemB: go! | SubsystemC: done

// ── Module / export facade pattern ──────────────────────────────
// In real codebases, the facade is often the module's public export:
//
// auth/index.js  ← facade
//   export { login, logout, refreshToken }
//   (internally uses TokenService, SessionStore, CryptoUtil)
//
// import { login } from './auth'; // caller sees only three functions
